// Package brand embeds the RCP For All Camera logo (construction guide:
// docs/brand/logo.md). The SVG files are generated by
// docs/brand/gen_logo.py; edit the script, not the files.
package brand

import (
	_ "embed"

	"fyne.io/fyne/v2"
)

var (
	//go:embed logo.svg
	logoSVG []byte
	//go:embed mark-dark.svg
	markDarkSVG []byte
	//go:embed mark-light.svg
	markLightSVG []byte
)

// Logo is the app icon: the iris mark on its graphite tile.
var Logo = fyne.NewStaticResource("rcp-logo.svg", logoSVG)

// Mark returns the mark without its tile, for a dark or a light background.
func Mark(dark bool) fyne.Resource {
	if dark {
		return fyne.NewStaticResource("rcp-mark-dark.svg", markDarkSVG)
	}
	return fyne.NewStaticResource("rcp-mark-light.svg", markLightSVG)
}
